import React from "react";  
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import Home from "./components/Home";
import Login from "./components/Login";
import Registration from "./components/Registration";
import Logout from "./components/Logout";
import { ToastContainer, toast } from "react-toastify";
import 'react-toastify/dist/ReactToastify.css';

function App() {
  // Example of a function that triggers a toast notification
  const showToast = () => {
    toast.success("Welcome to the app!", {
      position: "top-right",
      autoClose: 3000,
      hideProgressBar: false,
      closeOnClick: true,
      pauseOnHover: true,
      draggable: true,
      progress: undefined,
    });
  };

  return (
    <Router>
      <div className="container mt-4">
        <nav>
          <Link to="/">Home</Link> | 
          <Link to="/login">Login</Link> | 
          <Link to="/register">Register</Link> | 
          <Link to="/logout">Logout</Link>
        </nav>

        {/* Call showToast function to display a toast */}
        <button onClick={showToast} className="btn btn-primary mt-3">Show Toast</button>

        <Routes>
          {/* Define routes for your pages */}
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Registration />} />
          <Route path="/logout" element={<Logout />} />
        </Routes>

        {/* ToastContainer should be placed once in the app */}
        <ToastContainer />
      </div>
    </Router>
  );
}

export default App;
